#!/usr/bin/env bash

set -euo pipefail

# Resolve this directory so the launcher and backend can live together
# without hardcoding the user's home directory.
SCRIPT_DIR="$(
    cd -- "$(dirname -- "${BASH_SOURCE[0]}")"
    pwd
)"

BACKEND="$SCRIPT_DIR/cliphist-rofi-backend.sh"

# Temporary image previews generated by the backend.
TMP_DIR="${XDG_RUNTIME_DIR:-/tmp}/cliphist-rofi"

# Optional clipboard-specific Rofi theme.
ROFI_THEME="$HOME/.config/rofi/sx/clipboard.rasi"


# Remove thumbnails left from the previous invocation.
rm -rf "$TMP_DIR"
mkdir -p "$TMP_DIR"


# Base Rofi configuration.
ROFI_ARGS=(
    -modi "clipboard:$BACKEND"
    -show clipboard
    -show-icons
)

# Use the dedicated clipboard theme when available.
# Otherwise Rofi simply falls back to the user's normal theme.
if [[ -f "$ROFI_THEME" ]]; then
    ROFI_ARGS+=(
        -theme "$ROFI_THEME"
    )
fi


# Open clipboard history.
rofi "${ROFI_ARGS[@]}"

# The previews are no longer needed once the picker closes.
rm -rf "$TMP_DIR"